CREATE FUNCTION combat_panel_private.pg_movement_offers(p_context uuid,p_expected bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $fn$
DECLARE c combat_panel_private.contexts%ROWTYPE; ctx combat_consumer_private.activities%ROWTYPE;
 a public.combat_v2_actors%ROWTYPE;b combat_spatial.actor_states%ROWTYPE;i combat_spatial.arena_instances%ROWTYPE;
 remaining numeric; step record; k text; prefix text; keys text[]:='{}'; item jsonb; caps jsonb:='[]';
 oid uuid;gid uuid;direction_id uuid;distances uuid;dir text;cap combat_spatial.movement_capabilities%ROWTYPE;
BEGIN
 c:=combat_panel_private.owned_context(p_context,p_expected);
 IF c.activity_kind<>'ordinary_v2' OR c.command_actor_id IS NULL OR c.round_id IS NULL THEN RETURN;END IF;
 SELECT * INTO ctx FROM combat_consumer_private.activities WHERE session_id=c.activity_id;
 IF ctx.phase<>'action' OR ctx.turn_actor_id<>c.command_actor_id OR ctx.exchange_id<>c.round_id
  OR ctx.policy_id<>'staff_test_no_persistent_resources_v1'
  OR NOT combat_consumer_private.staff_test_allowed(c.location_id,ARRAY[auth.uid()],false)
  OR NOT EXISTS(SELECT 1 FROM public.locations WHERE id=c.location_id AND is_test)
  OR public.combat_v2_values_written(c.activity_id) THEN RETURN; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=c.command_actor_id AND session_id=c.activity_id
  AND actor_kind='pg' AND companion_id IS NULL AND controller_user=auth.uid() AND state='attivo';
 IF combat_panel_private.movement_block_reason(a.id) IS NOT NULL THEN RETURN; END IF;
 remaining:=(combat_panel_private.movement_budget(a.id,c.round_id)->>'remaining_m')::numeric;
 IF remaining<1 THEN RETURN;END IF;
 IF EXISTS(SELECT 1 FROM combat_panel_private.offers WHERE context_id=c.id AND context_version=c.context_version
  AND state='offered' AND source_payload->>'dispatch'='pg_movement') THEN RETURN;END IF;
 SELECT * INTO STRICT i FROM combat_spatial.arena_instances WHERE encounter_id=a.session_id AND context_source='ordinary' AND state='open';
 SELECT * INTO STRICT b FROM combat_spatial.actor_states WHERE instance_id=i.instance_id AND actor_id=a.id AND state='active';
 IF b.controller_principal_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'pg_movement_controller_stale' USING ERRCODE='40001';END IF;
 prefix:='pgmove:'||c.round_id||':'||b.body_version||':';
 FOR step IN SELECT d.dx,d.dy,d.direction,m.metres FROM (VALUES(1,0,'right'),(-1,0,'left'),(0,1,'down'),(0,-1,'up'))d(dx,dy,direction)
  CROSS JOIN LATERAL generate_series(1,floor(remaining)::integer)m(metres) LOOP
  k:=prefix||step.direction||':'||step.metres||':'||remaining;keys:=array_append(keys,k);
  INSERT INTO combat_spatial.movement_semantic_choices(instance_id,actor_id,choice_key,endpoint_x_m,endpoint_y_m,max_budget_m,choice_version,enabled)
   VALUES(i.instance_id,a.id,k,b.x_m+step.dx*step.metres,b.y_m+step.dy*step.metres,remaining,1,true)
   ON CONFLICT(instance_id,actor_id,choice_key) DO NOTHING;
 END LOOP;
 UPDATE combat_spatial.movement_semantic_choices SET enabled=false,choice_version=choice_version+1
  WHERE instance_id=i.instance_id AND actor_id=a.id AND enabled AND left(choice_key,7)='pgmove:' AND NOT(choice_key=ANY(keys));
 FOR item IN SELECT value FROM jsonb_array_elements(combat_spatial.movement_options(i.instance_id,a.id,remaining)) LOOP
  IF item->>'intent'=ANY(keys) AND (item->>'distance_m')::numeric>0 THEN
   SELECT * INTO STRICT cap FROM combat_spatial.movement_capabilities WHERE capability_id=(item->>'option_id')::uuid AND actor_id=a.id;
   dir:=CASE WHEN cap.end_x_m>cap.start_x_m THEN 'right' WHEN cap.end_x_m<cap.start_x_m THEN 'left' WHEN cap.end_y_m>cap.start_y_m THEN 'down' ELSE 'up' END;
   caps:=caps||jsonb_build_array(jsonb_build_object('capability_id',cap.capability_id,'direction',dir,'distance_m',item->'distance_m'));
  END IF;
 END LOOP;
 IF jsonb_array_length(caps)=0 THEN RETURN;END IF;
 oid:=combat_panel_private.create_offer(c.id,c.context_version,'control','control','Muovi il personaggio',false,
  jsonb_build_object('adapter','ordinary_v2','dispatch','pg_movement'));
 gid:=combat_panel_private.add_group(oid,'Direzione','movement_direction','single',1,1);
 FOREACH dir IN ARRAY ARRAY['up','right','down','left'] LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(caps) WHERE value->>'direction'=dir) THEN CONTINUE;END IF;
  direction_id:=combat_panel_private.add_choice(gid,CASE dir WHEN 'up' THEN 'Su' WHEN 'right' THEN 'Destra' WHEN 'down' THEN 'Giù' ELSE 'Sinistra' END,'{}'::jsonb,NULL,dir);
  distances:=combat_panel_private.add_group(oid,'Distanza','movement_distance','single',1,1,direction_id);
  FOR item IN SELECT DISTINCT ON ((value->>'distance_m')::numeric) value FROM jsonb_array_elements(caps)
    WHERE value->>'direction'=dir ORDER BY (value->>'distance_m')::numeric,value->>'capability_id' LOOP
   PERFORM combat_panel_private.add_choice(distances,(item->>'distance_m')::numeric::integer||' m',jsonb_build_object('movement_capability_id',item->'capability_id'),(item->>'distance_m')::numeric,dir);
  END LOOP;
 END LOOP;
END $fn$;
REVOKE ALL ON FUNCTION combat_panel_private.pg_movement_offers(uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION combat_panel_private.pg_movement_offers(uuid,bigint) TO postgres;
CREATE FUNCTION combat_panel_private.commit_pg_movement(p_command jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $fn$
DECLARE p jsonb;uid uuid:=auth.uid();key uuid;fp text;prior combat_panel_private.request_receipts%ROWTYPE;
 o combat_panel_private.offers%ROWTYPE;c combat_panel_private.contexts%ROWTYPE;ctx combat_consumer_private.activities%ROWTYPE;
 a public.combat_v2_actors%ROWTYPE;cap combat_spatial.movement_capabilities%ROWTYPE;i combat_spatial.arena_instances%ROWTYPE;
 body combat_spatial.actor_states%ROWTYPE; cost_cap combat_panel_private.movement_cost_capabilities%ROWTYPE;
 env jsonb;resolved jsonb;selected uuid[];payload jsonb;cid uuid;count_caps integer:=0;remaining numeric;result jsonb;receipt jsonb;event jsonb;label text;eid uuid;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000';END IF;
 p:=combat_panel_private.validate_command(p_command);key:=(p->>'request_key')::uuid;fp:=public.combat_v2_sha256(p);
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-request:'||uid::text||':'||key::text,731));
 SELECT * INTO prior FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=key;
 IF FOUND THEN
  IF prior.command_fingerprint<>fp THEN RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023';END IF;
  RETURN jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO STRICT o FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid
  AND kind='control' AND operation='control' AND source_payload->>'adapter'='ordinary_v2' AND source_payload->>'dispatch'='pg_movement';
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE id=o.context_id AND principal_user=uid;
 IF c.activity_kind<>'ordinary_v2' OR c.round_id IS NULL
  OR c.location_id IS DISTINCT FROM (p->>'location_id')::uuid OR c.activity_id IS DISTINCT FROM (p->>'activity_id')::uuid
  OR combat_panel_private.access_reason(c.location_id,'ordinary_v2') IS NOT NULL
  OR combat_panel_private.location_adapter(c.location_id)<>'ordinary_v2' THEN RAISE EXCEPTION 'pg_movement_scope_invalid' USING ERRCODE='42501';END IF;
 PERFORM public.combat_v2_lock_round(c.round_id);
 env:=combat_panel_private.ordinary_projection(c.location_id,c.command_actor_id);
 IF env->>'status'<>'ready' THEN RAISE EXCEPTION 'panel_source_not_ready' USING ERRCODE='40001';END IF;
 PERFORM 1 FROM combat_panel_private.contexts WHERE id=c.id FOR UPDATE;
 c:=combat_panel_private.owned_context(c.id,(p->>'context_version')::bigint);
 SELECT * INTO STRICT o FROM combat_panel_private.offers WHERE id=o.id FOR UPDATE;
 IF o.state<>'offered' OR o.context_version<>c.context_version OR o.source_fingerprint IS DISTINCT FROM c.source_fingerprint
  OR o.scene_version IS DISTINCT FROM c.scene_version OR o.actor_id IS DISTINCT FROM c.command_actor_id
  OR length(btrim(p->>'narrative_text'))<>0 OR jsonb_array_length(p->'inputs')<>0 THEN
  RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='40001';END IF;
 SELECT * INTO STRICT ctx FROM combat_consumer_private.activities WHERE session_id=c.activity_id FOR UPDATE;
 IF ctx.phase<>'action' OR ctx.turn_actor_id<>c.command_actor_id OR ctx.exchange_id<>c.round_id
  OR ctx.policy_id<>'staff_test_no_persistent_resources_v1' OR NOT combat_consumer_private.staff_test_allowed(c.location_id,ARRAY[uid],false)
  OR NOT EXISTS(SELECT 1 FROM public.locations WHERE id=c.location_id AND is_test)
  OR public.combat_v2_values_written(c.activity_id) THEN RAISE EXCEPTION 'pg_movement_scope_invalid' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=c.command_actor_id AND session_id=c.activity_id
  AND actor_kind='pg' AND companion_id IS NULL AND controller_user=uid AND state='attivo' FOR UPDATE;
 IF combat_panel_private.movement_block_reason(a.id) IS NOT NULL THEN RAISE EXCEPTION 'panel_body_movement_blocked' USING ERRCODE='40001';END IF;
 SELECT coalesce(array_agg((value#>>'{}')::uuid),'{}'::uuid[]) INTO selected FROM jsonb_array_elements(p->'selected_option_ids');
 resolved:=combat_panel_private.resolve_selections(o.id,selected,p->'inputs');
 FOR payload IN SELECT choice->'payload' FROM jsonb_array_elements(resolved->'groups')g(v)
  CROSS JOIN LATERAL jsonb_array_elements(v->'options')x(choice) LOOP
  IF payload?'movement_capability_id' THEN count_caps:=count_caps+1;cid:=(payload->>'movement_capability_id')::uuid;END IF;
 END LOOP;
 IF count_caps<>1 OR cid IS NULL THEN RAISE EXCEPTION 'pg_movement_selection_invalid' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT cap FROM combat_spatial.movement_capabilities WHERE capability_id=cid AND actor_id=a.id FOR UPDATE;
 SELECT * INTO STRICT i FROM combat_spatial.arena_instances WHERE instance_id=cap.instance_id AND encounter_id=c.activity_id AND context_source='ordinary' AND state='open' FOR UPDATE;
 SELECT * INTO STRICT body FROM combat_spatial.actor_states WHERE instance_id=i.instance_id AND actor_id=a.id AND state='active' FOR UPDATE;
 SELECT * INTO STRICT cost_cap FROM combat_panel_private.movement_cost_capabilities WHERE capability_id=cid;
 remaining:=(combat_panel_private.movement_budget(a.id,c.round_id)->>'remaining_m')::numeric;
 IF cap.state<>'offered' OR cap.map_version<>i.map_version OR cap.actor_body_version<>body.body_version
  OR body.controller_principal_id IS DISTINCT FROM uid OR (cap.start_x_m,cap.start_y_m) IS DISTINCT FROM (body.x_m,body.y_m)
  OR left(cap.choice_key,length('pgmove:'||c.round_id||':'||body.body_version||':'))<>'pgmove:'||c.round_id||':'||body.body_version||':'
  OR cost_cap.budget_m>remaining OR combat_spatial.distance_m(cap.start_x_m,cap.start_y_m,cap.end_x_m,cap.end_y_m)<=0
  OR (cap.end_x_m<>cap.start_x_m AND cap.end_y_m<>cap.start_y_m) THEN RAISE EXCEPTION 'pg_movement_capability_stale' USING ERRCODE='40001';END IF;
 result:=combat_spatial.movement_commit(cid,key,o.id);eid:=(result->>'event_id')::uuid;
 INSERT INTO clan_marionettisti_private.movement_receipts(request_key,round_id,owner_actor_id,body_actor_id,capability_id,distance_m,result)
  VALUES(key,c.round_id,a.id,a.id,cid,(result->>'d_eff_m')::numeric,result);
 UPDATE combat_consumer_private.activities SET context_version=context_version+1,last_action_at=clock_timestamp() WHERE session_id=c.activity_id;
 SELECT value->>'display_name' INTO label FROM jsonb_array_elements(env->'actors') WHERE value->>'actor_id'=a.id::text;
 env:=combat_panel_private.ordinary_projection(c.location_id,a.id);
 event:=jsonb_build_object('event_id',eid,'event_kind','movement','actor_id',a.id,'display_name',label,'label_version',c.context_version,
  'target_actor_id',NULL,'target_display_name',NULL,'target_label_version',NULL,'summary',label||' si sposta di '||(result->>'d_eff_m')||' m.');
 receipt:=jsonb_build_object('receipt_id',eid,'request_key',key,'operation','control','replayed',false,'activity_id',c.activity_id,'round_id',c.round_id,
  'context_version_before',o.context_version,'context_version_after',env#>'{context,version}','declaration_id',NULL,'report_id',NULL,
  'values_written',false,'display_events',jsonb_build_array(event));
 env:=jsonb_set(env,'{receipt}',receipt);
 UPDATE combat_panel_private.offers SET state='consumed',consumed_request_key=key WHERE id=o.id;
 INSERT INTO combat_panel_private.request_receipts(principal_user,request_key,command_fingerprint,offer_id,event_id,viewer_envelope)
  VALUES(uid,key,fp,o.id,eid,env);
 RETURN env;
END $fn$;
REVOKE ALL ON FUNCTION combat_panel_private.commit_pg_movement(jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION combat_panel_private.commit_pg_movement(jsonb) TO postgres;
CREATE OR REPLACE FUNCTION combat_panel_private.ordinary_options(p_location uuid, p_actor uuid, p_expected bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE env jsonb; src jsonb; c combat_panel_private.contexts%ROWTYPE; rid uuid;
 item jsonb; companion_moves jsonb:='[]'; rendered jsonb; ignored uuid;
BEGIN
 -- Ordine coerente con il commit del motore: round/sessione prima del
 -- contesto del nuovo pannello. Non si blocca il POV prima delle risorse.
 SELECT exchange_id INTO rid FROM combat_consumer_private.activities
   WHERE location_id=p_location AND phase<>'closed';
 IF rid IS NOT NULL THEN PERFORM public.combat_v2_lock_round(rid);
 ELSE PERFORM 1 FROM public.locations WHERE id=p_location FOR UPDATE; END IF;
 env:=combat_panel_private.ordinary_projection(p_location,p_actor);
 IF env->>'status' IS DISTINCT FROM 'ready' THEN RETURN env; END IF;
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE location_id=p_location
   AND principal_user=auth.uid() AND command_actor_id IS NOT DISTINCT FROM (env#>>'{viewer,command_actor_id}')::uuid;
 IF c.context_version IS DISTINCT FROM p_expected THEN
   RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM combat_panel_private.offers WHERE context_id=c.id
   AND context_version=c.context_version AND state='offered') THEN
   src:=combat_panel_private.consumer_state_authoritative(p_location);
   src:=combat_panel_private.consumer_options_authoritative(p_location,(src#>>'{context,version}')::bigint);
   IF src->>'status' IS DISTINCT FROM 'ready' THEN
     RAISE EXCEPTION 'panel_source_options_not_ready' USING ERRCODE='40001'; END IF;
   -- I producer gia rilasciati possono preparare il link iniziale. Riprendere
   -- la projection autorizzata e la nuova versione prima di importare offerte.
   env:=combat_panel_private.ordinary_projection(p_location,p_actor);
   SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE location_id=p_location
     AND principal_user=auth.uid() AND command_actor_id IS NOT DISTINCT FROM (env#>>'{viewer,command_actor_id}')::uuid;
   FOR item IN SELECT value FROM jsonb_array_elements(src->'offers') LOOP
     IF jsonb_typeof(item->'companion_movement')='object' THEN
       companion_moves:=companion_moves||jsonb_build_array(item);
     ELSE
       ignored:=combat_panel_private.import_ordinary_offer(c.id,c.context_version,item,(src#>>'{context,version}')::bigint);
     END IF;
   END LOOP;
   IF jsonb_array_length(companion_moves)>0 THEN
     ignored:=combat_panel_private.import_companion_moves(c.id,c.context_version,companion_moves,(src#>>'{context,version}')::bigint);
   END IF;
 END IF;
 PERFORM combat_panel_private.multiplication_ordinary_attack_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.multiplication_companion_ordinary_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.multiplication_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.immobilization_escape_offers(c.id,c.context_version,env);
 PERFORM clan_sabaku_private.clone_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.pg_movement_offers(c.id,c.context_version);
 PERFORM combat_panel_private.master_open_offers(c.id,c.context_version);
 SELECT coalesce(jsonb_agg(combat_panel_private.offer_projection(id) ORDER BY created_at,id),'[]'::jsonb)
   INTO rendered FROM combat_panel_private.offers WHERE context_id=c.id
     AND context_version=c.context_version AND state='offered';
 RETURN jsonb_set(jsonb_set(env,'{offers}',rendered),'{movement_explanations}',
   coalesce(combat_panel_private.movement_explanations(c.id,c.context_version),'null'::jsonb));
END $function$
;
CREATE OR REPLACE FUNCTION public.combat_panel_commit_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p jsonb; uid uuid:=auth.uid(); key uuid; fp text; adapter text; reason text;
 prior combat_panel_private.request_receipts%ROWTYPE; offer combat_panel_private.offers%ROWTYPE;
 code text; message text; recovery text;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 p:=combat_panel_private.validate_command(p_command); key:=(p->>'request_key')::uuid; fp:=public.combat_v2_sha256(p);
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-request:'||uid::text||':'||key::text,731));
 SELECT * INTO prior FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=key;
 IF prior.request_key IS NOT NULL THEN
   IF prior.command_fingerprint<>fp THEN RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO offer FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid;
 IF offer.id IS NULL THEN RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='42501'; END IF;
 adapter:=offer.source_payload->>'adapter';
 reason:=combat_panel_private.access_reason((p->>'location_id')::uuid,adapter);
 IF reason IS NOT NULL THEN RAISE EXCEPTION 'panel_access_rejected' USING ERRCODE='42501'; END IF;
 IF adapter IS DISTINCT FROM combat_panel_private.location_adapter((p->>'location_id')::uuid) THEN
   RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 IF offer.kind='administration' AND offer.operation='open'
   AND offer.source_payload->>'dispatch'='master_session_open' THEN
   RETURN combat_panel_private.commit_master_open(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='sabaku_clone' THEN
   RETURN clan_sabaku_private.commit_clone(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='immobilization_escape' THEN
   RETURN combat_panel_private.commit_immobilization_escape(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='multiplication' THEN
   RETURN combat_panel_private.commit_multiplication(p); END IF;
 IF adapter='ordinary_v2' AND offer.kind='control' AND offer.operation='control' AND offer.source_payload->>'dispatch'='pg_movement' THEN
   RETURN combat_panel_private.commit_pg_movement(p); END IF;
 IF adapter='ordinary_v2' THEN RETURN combat_panel_private.commit_ordinary(p); END IF;
 IF adapter='master_v2' THEN
   IF offer.kind='control' AND offer.source_payload->>'dispatch'='sabaku_control' THEN
     RETURN clan_sabaku_private.commit_master_control(p); END IF;
   IF offer.kind='control' AND offer.source_payload->>'dispatch'='companion_control' THEN
     RETURN combat_panel_private.commit_master_companion(p); END IF;
   IF offer.kind='administration' THEN RETURN combat_panel_private.commit_master_admin(p); END IF;
   RETURN combat_panel_private.commit_master_actor(p);
 END IF;
 RAISE EXCEPTION 'panel_dispatch_not_available' USING ERRCODE='22023';
EXCEPTION WHEN OTHERS THEN
 -- Questo ramo viene raggiunto dopo il rollback dell'intera sottotransazione
 -- della richiesta. Non comprende timeout/disconnessioni senza risposta DB.
 code:=CASE WHEN SQLSTATE='28000' THEN 'authentication_required'
   WHEN SQLERRM='panel_request_key_conflict' THEN 'request_key_conflict'
   WHEN SQLSTATE='42501' THEN 'not_authorized'
   WHEN SQLSTATE='40001' THEN 'context_changed'
   WHEN SQLSTATE LIKE '22%' THEN 'selection_rejected' ELSE 'operation_rejected' END;
 message:=CASE code WHEN 'authentication_required' THEN 'Accedi nuovamente per continuare.'
   WHEN 'request_key_conflict' THEN 'Questa richiesta è già associata a un altro invio. Verifica lo stato prima di continuare.'
   WHEN 'not_authorized' THEN 'Questa operazione non è disponibile per il tuo accesso.'
   WHEN 'context_changed' THEN 'Lo scontro è cambiato. Rileggi lo stato e scegli di nuovo.'
   WHEN 'selection_rejected' THEN 'Le scelte non sono più valide. Rileggi le opzioni.'
   ELSE 'Il server ha rifiutato l’operazione. Rileggi lo stato; se il problema resta, informa lo staff.' END;
 recovery:=CASE WHEN code='authentication_required' THEN 'authenticate'
   WHEN code='request_key_conflict' THEN 'contact_staff' ELSE 'refresh' END;
 RETURN jsonb_build_object('schema_version','combat-panel-error/1','status','rejected','request_key',key,
   'code',code,'message',message,'recovery',recovery);
END $function$
;
COMMIT;

SET search_path=pg_catalog;
SELECT jsonb_build_object('at',clock_timestamp(),'database',current_database(),'tables',54,'all_tables_zero_rows',true,'structure_md5',(SELECT md5(jsonb_build_object('tables',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname NOT IN('pg_catalog','information_schema')),'columns',(SELECT jsonb_agg(jsonb_build_object('relation',a.attrelid::regclass::text,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attrelid::regclass::text,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped AND c.relkind='r' AND n.nspname NOT IN('pg_catalog','information_schema')),'constraints',(SELECT jsonb_agg(jsonb_build_object('relation',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c WHERE c.conrelid IN(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname NOT IN('pg_catalog','information_schema'))),'indexes',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY i.indexrelid::regclass::text) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN('pg_catalog','information_schema')))::text)),'functions',(SELECT jsonb_object_agg(format('%I.%I(%s)',n.nspname,p.proname,array_to_string(ARRAY(SELECT pg_catalog.format_type(a.arg_oid,NULL) FROM unnest(p.proargtypes) WITH ORDINALITY a(arg_oid,ord) ORDER BY ord),',')),jsonb_build_object('md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind IN('f','p') AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema'))::text;

SET search_path=pg_catalog,public,extensions,auth;
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='20s';
DO $pin$ BEGIN
IF md5(pg_get_functiondef('combat_panel_private.ordinary_options(uuid,uuid,bigint)'::regprocedure)) IS DISTINCT FROM 'a0258da001e61048b0adc2ba724a482a' THEN RAISE EXCEPTION 'pg_movement_recovery_drift';END IF;
IF md5(pg_get_functiondef('combat_panel_commit_v1(jsonb)'::regprocedure)) IS DISTINCT FROM '84860632d828931cea773b83c583548e' THEN RAISE EXCEPTION 'pg_movement_recovery_drift';END IF;
IF md5(pg_get_functiondef('combat_panel_private.pg_movement_offers(uuid,bigint)'::regprocedure)) IS DISTINCT FROM 'd6a6d6e09949d59cdc7a9ba90f9bf703' THEN RAISE EXCEPTION 'pg_movement_recovery_drift';END IF;
IF md5(pg_get_functiondef('combat_panel_private.commit_pg_movement(jsonb)'::regprocedure)) IS DISTINCT FROM '737d8d43958cbe5be62d518eb6e1c67a' THEN RAISE EXCEPTION 'pg_movement_recovery_drift';END IF;END $pin$;
CREATE OR REPLACE FUNCTION combat_panel_private.ordinary_options(p_location uuid, p_actor uuid, p_expected bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE env jsonb; src jsonb; c combat_panel_private.contexts%ROWTYPE; rid uuid;
 item jsonb; companion_moves jsonb:='[]'; rendered jsonb; ignored uuid;
BEGIN
 -- Ordine coerente con il commit del motore: round/sessione prima del
 -- contesto del nuovo pannello. Non si blocca il POV prima delle risorse.
 SELECT exchange_id INTO rid FROM combat_consumer_private.activities
   WHERE location_id=p_location AND phase<>'closed';
 IF rid IS NOT NULL THEN PERFORM public.combat_v2_lock_round(rid);
 ELSE PERFORM 1 FROM public.locations WHERE id=p_location FOR UPDATE; END IF;
 env:=combat_panel_private.ordinary_projection(p_location,p_actor);
 IF env->>'status' IS DISTINCT FROM 'ready' THEN RETURN env; END IF;
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE location_id=p_location
   AND principal_user=auth.uid() AND command_actor_id IS NOT DISTINCT FROM (env#>>'{viewer,command_actor_id}')::uuid;
 IF c.context_version IS DISTINCT FROM p_expected THEN
   RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM combat_panel_private.offers WHERE context_id=c.id
   AND context_version=c.context_version AND state='offered') THEN
   src:=combat_panel_private.consumer_state_authoritative(p_location);
   src:=combat_panel_private.consumer_options_authoritative(p_location,(src#>>'{context,version}')::bigint);
   IF src->>'status' IS DISTINCT FROM 'ready' THEN
     RAISE EXCEPTION 'panel_source_options_not_ready' USING ERRCODE='40001'; END IF;
   -- I producer gia rilasciati possono preparare il link iniziale. Riprendere
   -- la projection autorizzata e la nuova versione prima di importare offerte.
   env:=combat_panel_private.ordinary_projection(p_location,p_actor);
   SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE location_id=p_location
     AND principal_user=auth.uid() AND command_actor_id IS NOT DISTINCT FROM (env#>>'{viewer,command_actor_id}')::uuid;
   FOR item IN SELECT value FROM jsonb_array_elements(src->'offers') LOOP
     IF jsonb_typeof(item->'companion_movement')='object' THEN
       companion_moves:=companion_moves||jsonb_build_array(item);
     ELSE
       ignored:=combat_panel_private.import_ordinary_offer(c.id,c.context_version,item,(src#>>'{context,version}')::bigint);
     END IF;
   END LOOP;
   IF jsonb_array_length(companion_moves)>0 THEN
     ignored:=combat_panel_private.import_companion_moves(c.id,c.context_version,companion_moves,(src#>>'{context,version}')::bigint);
   END IF;
 END IF;
 PERFORM combat_panel_private.multiplication_ordinary_attack_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.multiplication_companion_ordinary_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.multiplication_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.immobilization_escape_offers(c.id,c.context_version,env);
 PERFORM clan_sabaku_private.clone_offers(c.id,c.context_version,env);
 PERFORM combat_panel_private.master_open_offers(c.id,c.context_version);
 SELECT coalesce(jsonb_agg(combat_panel_private.offer_projection(id) ORDER BY created_at,id),'[]'::jsonb)
   INTO rendered FROM combat_panel_private.offers WHERE context_id=c.id
     AND context_version=c.context_version AND state='offered';
 RETURN jsonb_set(jsonb_set(env,'{offers}',rendered),'{movement_explanations}',
   coalesce(combat_panel_private.movement_explanations(c.id,c.context_version),'null'::jsonb));
END $function$;
CREATE OR REPLACE FUNCTION public.combat_panel_commit_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p jsonb; uid uuid:=auth.uid(); key uuid; fp text; adapter text; reason text;
 prior combat_panel_private.request_receipts%ROWTYPE; offer combat_panel_private.offers%ROWTYPE;
 code text; message text; recovery text;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 p:=combat_panel_private.validate_command(p_command); key:=(p->>'request_key')::uuid; fp:=public.combat_v2_sha256(p);
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-request:'||uid::text||':'||key::text,731));
 SELECT * INTO prior FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=key;
 IF prior.request_key IS NOT NULL THEN
   IF prior.command_fingerprint<>fp THEN RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO offer FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid;
 IF offer.id IS NULL THEN RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='42501'; END IF;
 adapter:=offer.source_payload->>'adapter';
 reason:=combat_panel_private.access_reason((p->>'location_id')::uuid,adapter);
 IF reason IS NOT NULL THEN RAISE EXCEPTION 'panel_access_rejected' USING ERRCODE='42501'; END IF;
 IF adapter IS DISTINCT FROM combat_panel_private.location_adapter((p->>'location_id')::uuid) THEN
   RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 IF offer.kind='administration' AND offer.operation='open'
   AND offer.source_payload->>'dispatch'='master_session_open' THEN
   RETURN combat_panel_private.commit_master_open(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='sabaku_clone' THEN
   RETURN clan_sabaku_private.commit_clone(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='immobilization_escape' THEN
   RETURN combat_panel_private.commit_immobilization_escape(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='multiplication' THEN
   RETURN combat_panel_private.commit_multiplication(p); END IF;
 IF adapter='ordinary_v2' THEN RETURN combat_panel_private.commit_ordinary(p); END IF;
 IF adapter='master_v2' THEN
   IF offer.kind='control' AND offer.source_payload->>'dispatch'='sabaku_control' THEN
     RETURN clan_sabaku_private.commit_master_control(p); END IF;
   IF offer.kind='control' AND offer.source_payload->>'dispatch'='companion_control' THEN
     RETURN combat_panel_private.commit_master_companion(p); END IF;
   IF offer.kind='administration' THEN RETURN combat_panel_private.commit_master_admin(p); END IF;
   RETURN combat_panel_private.commit_master_actor(p);
 END IF;
 RAISE EXCEPTION 'panel_dispatch_not_available' USING ERRCODE='22023';
EXCEPTION WHEN OTHERS THEN
 -- Questo ramo viene raggiunto dopo il rollback dell'intera sottotransazione
 -- della richiesta. Non comprende timeout/disconnessioni senza risposta DB.
 code:=CASE WHEN SQLSTATE='28000' THEN 'authentication_required'
   WHEN SQLERRM='panel_request_key_conflict' THEN 'request_key_conflict'
   WHEN SQLSTATE='42501' THEN 'not_authorized'
   WHEN SQLSTATE='40001' THEN 'context_changed'
   WHEN SQLSTATE LIKE '22%' THEN 'selection_rejected' ELSE 'operation_rejected' END;
 message:=CASE code WHEN 'authentication_required' THEN 'Accedi nuovamente per continuare.'
   WHEN 'request_key_conflict' THEN 'Questa richiesta è già associata a un altro invio. Verifica lo stato prima di continuare.'
   WHEN 'not_authorized' THEN 'Questa operazione non è disponibile per il tuo accesso.'
   WHEN 'context_changed' THEN 'Lo scontro è cambiato. Rileggi lo stato e scegli di nuovo.'
   WHEN 'selection_rejected' THEN 'Le scelte non sono più valide. Rileggi le opzioni.'
   ELSE 'Il server ha rifiutato l’operazione. Rileggi lo stato; se il problema resta, informa lo staff.' END;
 recovery:=CASE WHEN code='authentication_required' THEN 'authenticate'
   WHEN code='request_key_conflict' THEN 'contact_staff' ELSE 'refresh' END;
 RETURN jsonb_build_object('schema_version','combat-panel-error/1','status','rejected','request_key',key,
   'code',code,'message',message,'recovery',recovery);
END $function$;
